function onAddNewRowClick(){gridOptions.api.applyTransaction({add:[{}]});lastRowIndex=gridOptions.api.getLastDisplayedRow();gridOptions.api.startEditingCell({rowIndex:lastRowIndex,colKey:"serviceTitle"})}function onCellValueChanged(n){if(n.column.colId==="serviceTitle"){var t=serviceData.find(t=>t.title===n.value);n.node.setDataValue("rate",t.rate);t.quantity>0&&n.node.setDataValue("Quantity",t.quantity)}n.column.colId!=="amount"&&(n.node.data.quantity>0?n.node.setDataValue("amount",n.node.data.quantity*n.node.data.rate):n.node.setDataValue("amount",n.node.data.rate));calculateTotalAmount();calculateExpiryDate()}function onRowValueChanged(n){var t=n.data}function calculateTotalAmount(){var n=0;gridOptions.api.forEachNode(t=>{n+=parseInt(t.data.amount)});document.getElementById("TotalAmount").value=n}function calculateExpiryDate(){var t=0,n;gridOptions.api.forEachNode(n=>{var i=parseInt(n.data.quantity);t=t<i?i:t});n=new Date(document.getElementById("StartDate").value);n.setMonth(n.getMonth()+1+t);document.getElementById("ExpiryDate").value=n.getFullYear()+"-"+("0"+(n.getMonth()+1)).slice(-2)+"-"+("0"+n.getDate()).slice(-2)}function getItemGridData(){gridOptions.api.stopEditing();var n=[];gridOptions.api.forEachNode(t=>{var i=serviceData.find(n=>n.title===t.data.serviceTitle);t.data.ServiceId=i.id;n.push(t.data)});document.getElementById("SaleItemsJson").value=encodeURIComponent(JSON.stringify(n))}class BtnCellRenderer{init(n){this.params=n;this.eGui=document.createElement("button");this.eGui.type="button";this.eGui.className="btn-sm btn-danger fa-solid fa-trash-can";this.btnClickedHandler=this.btnClickedHandler.bind(this);this.eGui.addEventListener("click",this.btnClickedHandler)}getGui(){return this.eGui}destroy(){this.eGui.removeEventListener("click",this.btnClickedHandler)}btnClickedHandler(){this.params.clicked(this.params.node)}}var serviceData=[];const gridOptions={columnDefs:[{headerName:"Service",field:"serviceTitle",minWidth:170,cellEditor:"agSelectCellEditor",cellEditorParams:{values:[]}},{headerName:"Quantity",field:"quantity",maxWidth:115,cellEditor:NumericCellEditor},{field:"rate",cellEditor:NumericCellEditor,editable:!1},{headerName:"Amount",field:"amount",cellEditor:NumericCellEditor},{editable:!1,minWidth:70,maxWidth:70,headerName:"",cellRenderer:BtnCellRenderer,cellRendererParams:{clicked:function(n){gridOptions.api.applyTransaction({remove:[n.data]});calculateTotalAmount()}},headerComponentParams:{template:'<div class="ag-cell-label-container" role="presentation">  <span ref="eMenu" class="ag-header-icon ag-header-cell-menu-button"><\/span>  <div ref="eLabel" class="ag-header-cell-label" role="presentation">    <span ref="eSortOrder" class="ag-header-icon ag-sort-order" ><\/span>    <span ref="eSortAsc" class="ag-header-icon ag-sort-ascending-icon" ><\/span>    <span ref="eSortDesc" class="ag-header-icon ag-sort-descending-icon" ><\/span>    <span ref="eSortNone" class="ag-header-icon ag-sort-none-icon" ><\/span>    <button type="button" class = "btn-sm btn-info fa-solid fa-circle-plus" onClick = "onAddNewRowClick()"> <span ref="eText" class="ag-header-cell-text" role="columnheader"><\/span><\/button>    <span ref="eFilter" class="ag-header-icon ag-filter-icon"><\/span>  <\/div><\/div>'}}],defaultColDef:{flex:1,editable:!0},rowData:[],rowSelection:"single",animateRows:!0,editType:"fullRow",onCellValueChanged:onCellValueChanged,onRowValueChanged:onRowValueChanged};